8	import React, { useEffect, useState } from 'react';
9	import { useHistory, useLocation, useParams } from 'react-router-dom';
10	import { FormattedMessage, defineMessages, useIntl } from 'react-intl';
11	import { Helmet } from 'react-helmet';
12	import {
13	  useCategory,
14	  useCustomerId,
15	  useProductSearch,
16	  useShopperCustomersMutation,
17	  useShopperBasketsMutationHelper,
18	} from '@salesforce/commerce-sdk-react';
19	import { useServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
20	
21	// Components
22	import {
23	  Box,
24	  Flex,
25	  SimpleGrid,
26	  Grid,
27	  Select,
28	  Heading,
29	  Text,
30	  FormControl,
31	  Stack,
32	  useDisclosure,
33	  Button,
34	  Modal,
35	  ModalHeader,
36	  ModalBody,
37	  ModalFooter,
38	  ModalContent,
39	  ModalCloseButton,
40	  ModalOverlay,
41	  Drawer,
42	  DrawerBody,
43	  DrawerHeader,
44	  DrawerOverlay,
45	  DrawerContent,
46	  DrawerCloseButton,
47	} from '@salesforce/retail-react-app/app/components/shared/ui';
48	import type { BoxProps } from '@chakra-ui/layout';
49	
50	// Project Components
51	import Pagination from '@salesforce/retail-react-app/app/components/pagination';
52	import { Skeleton as ProductTileSkeleton } from '@salesforce/retail-react-app/app/components/product-tile';
53	import { ZimmProductCard } from '../../components/ui-kits/organisms/zimmProductCard';
54	import type { ZimmProductCardProps } from '../../components/ui-kits/organisms/zimmProductCard';
55	import { selectProductListCard } from './productListCardMapper';
56	// Already overridden in this repo (overrides/app/components/responsive) — relative import
57	// required, not the base path, per overrideStyling.md's "importing an already-overridden
58	// component from a new component" rule.
59	import { HideOnDesktop } from '../../components/responsive';
60	import Refinements from '@salesforce/retail-react-app/app/pages/product-list/partials/refinements';
61	import CategoryLinks from '@salesforce/retail-react-app/app/pages/product-list/partials/category-links';
62	import SelectedRefinements from '@salesforce/retail-react-app/app/pages/product-list/partials/selected-refinements';
63	import EmptySearchResults from '@salesforce/retail-react-app/app/pages/product-list/partials/empty-results';
64	import PageHeader from '@salesforce/retail-react-app/app/pages/product-list/partials/page-header';
65	import AbovePageHeader from '@salesforce/retail-react-app/app/pages/product-list/partials/above-page-header';
66	import PageDesignerPromotionalBanner from '@salesforce/retail-react-app/app/pages/product-list/partials/page-designer-promotional-banner';
67	import StoreInventoryFilter from '@salesforce/retail-react-app/app/pages/product-list/partials/inventory-filter';
68	import Island from '@salesforce/retail-react-app/app/components/island';
69	
70	// Icons — this repo's single source of truth is overrides/app/components/icons, never the
71	// base template path directly.
72	import { FilterIcon, ChevronDownIcon } from '../../components/icons';
73	
74	// Hooks
75	import { useLimitUrls, usePageUrls, useSortUrls, useSearchParams } from '@salesforce/retail-react-app/app/hooks';
76	import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
77	import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
78	import useDataCloud from '@salesforce/retail-react-app/app/hooks/use-datacloud';
79	import useActiveData from '@salesforce/retail-react-app/app/hooks/use-active-data';
80	
81	// Others
82	import { HTTPNotFound, HTTPError } from '@salesforce/pwa-kit-react-sdk/ssr/universal/errors';
83	import logger from '@salesforce/retail-react-app/app/utils/logger-instance';
84	
85	// Constants
86	import {
87	  DEFAULT_LIMIT_VALUES,
88	  API_ERROR_MESSAGE,
89	  MAX_CACHE_AGE,
90	  TOAST_ACTION_VIEW_WISHLIST,
91	  TOAST_MESSAGE_ADDED_TO_WISHLIST,
92	  TOAST_MESSAGE_REMOVED_FROM_WISHLIST,
93	  STALE_WHILE_REVALIDATE,
94	  STORE_LOCATOR_IS_ENABLED,
95	} from '@salesforce/retail-react-app/app/constants';
96	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
97	import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
98	import LoadingSpinner from '@salesforce/retail-react-app/app/components/loading-spinner';
99	import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';
100	import { isHydrated } from '@salesforce/retail-react-app/app/utils/utils';
101	
102	// NOTE: You can ignore certain refinements on a template level by updating the below
103	// list of ignored refinements.
104	const REFINEMENT_DISALLOW_LIST = ['c_isNew'];
105	
106	// SFCC-83/84 quick test integration — this page's own toast constants (imported above) are all
107	// wishlist-specific; add-to-bag needed its own message rather than reusing one of those under a
108	// misleading label.
109	const messages = defineMessages({
110	  addedToBag: { id: 'product_list.toast.added_to_bag', defaultMessage: 'Added to bag' },
111	});
112	
113	/**
114	 * Props as declared by the base template's own (removed) PropTypes, plus `staticContext` — the
115	 * react-router route-component prop this page receives when rendered via `<Route
116	 * component={ProductList} />` (v5.3.4, a plain JS package with no bundled or @types definitions
117	 * in this repo, so `unknown` is the honest ceiling here — same reasoning as `category` below).
118	 * Everything else lands in `...rest` and is spread onto the root `<Box>` exactly as it did in
119	 * the untyped base file; this type only makes the existing shape explicit, it does not change
120	 * what is accepted at runtime.
121	 */
122	type ProductListProps = {
123	  onAddToWishlistClick?: () => void;
124	  onRemoveWishlistClick?: () => void;
125	  category?: unknown;
126	  isLoading?: boolean;
127	  staticContext?: unknown;
128	} & Record<string, unknown>;
129	
130	/**
131	 * Quick test integration only (SFCC-83/84) — swaps the base `ProductTile` for the shared
132	 * `ZimmProductCard` (`variation: 'plp'`) so it can be exercised against a real PLP grid. Not the
133	 * final PLP implementation: it still needs the "product card group" component this grid doesn't
134	 * have yet. Owns its own `selectedSizeChipValue` local state — same pattern
135	 * `organisms/zimmProductCard/index.stories.tsx`'s own `LiveSizeSelectionCard` already uses —
136	 * since the page renders many of these and this can't be a single page-level state variable.
137	 */
138	type ProductListCardProps = Extract<ZimmProductCardProps, { variation: 'plp' }>;
139	
140	const ProductListCard = (cardProps: ProductListCardProps) => {
141	  const [selectedSizeChipValue, setSelectedSizeChipValue] = useState<string | undefined>(
142	    () => cardProps.selectedSizeChipValue,
143	  );
144	  const handleSizeChipSelect = (value: string) => {
145	    setSelectedSizeChipValue(value);
146	    cardProps.onSizeChipSelect?.(value);
147	  };
148	
149	  return (
150	    <ZimmProductCard
151	      {...cardProps}
152	      selectedSizeChipValue={selectedSizeChipValue}
153	      onSizeChipSelect={handleSizeChipSelect}
154	    />
155	  );
156	};
157	
158	/*
159	 * This is a simple product listing page. It displays a paginated list
160	 * of product hit objects. Allowing for sorting and filtering based on the
161	 * allowable filters and sort refinements.
162	 */
163	const ProductList = (props: ProductListProps) => {
164	  // Using destructuring to omit properties; we must rename `isLoading` because we use a different
165	  // `isLoading` later in this function.
166	  const { isLoading: _unusedIsLoading, staticContext: _unusedStaticContext, ...rest } = props;
167	  const { isOpen, onOpen, onClose } = useDisclosure();
168	  // `intl.formatMessage`/`intl.formatNumber`, never a destructured `{ formatMessage }`: the
169	  // base file's own original destructure tripped `@typescript-eslint/unbound-method` (the
170	  // established fix already used elsewhere in this codebase — see
171	  // zimmProductStyleCode/index.tsx) — consolidated to the one `intl` object throughout.
172	  const intl = useIntl();
173	  const navigate = useNavigation();
174	  const history = useHistory();
175	  const params = useParams<{ categoryId?: string }>();
176	  const location = useLocation();
177	  const toast = useToast();
178	  const { addItemToNewOrExistingBasket } = useShopperBasketsMutationHelper();
179	  // Passed into the card mapper rather than formatted there — keeps that mapper a pure function
180	  // with no react-intl dependency of its own, same split its own docblock documents.
181	  const formatPrice = (amount: number, currency: string) => intl.formatNumber(amount, { style: 'currency', currency });
182	  const einstein = useEinstein();
183	  const dataCloud = useDataCloud();
184	  const activeData = useActiveData();
185	  const { res } = useServerContext();
186	  const customerId = useCustomerId();
187	  const [searchParams, { stringify: stringifySearchParams }] = useSearchParams();
188	  const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
189	
190	  /**************** Page State ****************/
191	  const [filtersLoading, setFiltersLoading] = useState(false);
192	  const [wishlistLoading, setWishlistLoading] = useState<string[]>([]);
193	  const [sortOpen, setSortOpen] = useState(false);
194	  const [searchByInventory, setSearchByInventory] = useState<string | number | null>(null);
195	
196	  const urlParams = new URLSearchParams(location.search);
197	  const searchQuery = urlParams.get('q');
198	  const isSearch = !!searchQuery;
199	
200	  if (params.categoryId) {
201	    searchParams._refine.push(`cgid=${params.categoryId}`);
202	  }
203	
204	  /**************** Mutation Actions ****************/
205	  const { mutateAsync: createCustomerProductListItem } = useShopperCustomersMutation('createCustomerProductListItem');
206	  const { mutateAsync: deleteCustomerProductListItem } = useShopperCustomersMutation('deleteCustomerProductListItem');
207	
208	  /**************** Query Actions ****************/
209	  // _refine is an invalid param for useProductSearch, we don't want to pass it to API call
210	  const { _refine, ...restOfParams } = searchParams;
211	
212	  const refine = searchByInventory ? [..._refine, `ilids=${searchByInventory}`] : _refine;
213	
214	  const {
215	    isLoading,
216	    isFetched,
217	    isRefetching,
218	    data: productSearchResult,
219	  } = useProductSearch(
220	    {
221	      parameters: {
222	        ...restOfParams,
223	        perPricebook: true,
224	        allVariationProperties: true,
225	        allImages: true,
226	        expand: ['promotions', 'variations', 'prices', 'images', 'page_meta_tags', 'custom_properties'],
227	        refine,
228	      },
229	    },
230	    {
231	      keepPreviousData: true,
232	    },
233	  );
234	
235	  const { error, data: category } = useCategory(
236	    {
237	      parameters: {
238	        // `enabled` below gates the actual request on a real categoryId; the fallback here only
239	        // satisfies the hook's own parameter type (which does not accept `undefined`) for the
240	        // render where categoryId isn't present yet (e.g. a search-query route).
241	        id: params.categoryId ?? '',
242	      },
243	    },
244	    {
245	      enabled: !isSearch && !!params.categoryId,
246	    },
247	  );
248	
249	  // Apply disallow list to refinements.
250	  if (productSearchResult?.refinements) {
251	    productSearchResult.refinements = productSearchResult.refinements.filter(
252	      ({ attributeId }) => !REFINEMENT_DISALLOW_LIST.includes(attributeId),
253	    );
254	  }
255	
256	  /**************** Error Handling ****************/
257	  const errorStatus = (error as { response?: { status?: number } } | null)?.response?.status;
258	  switch (errorStatus) {
259	    case undefined:
260	      // No Error.
261	      break;
262	    case 404:
263	      throw new HTTPNotFound('Category Not Found.');
264	    default:
265	      throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
266	  }
267	
268	  /**************** Response Handling ****************/
269	  if (res) {
270	    res.set('Cache-Control', `s-maxage=${MAX_CACHE_AGE}, stale-while-revalidate=${STALE_WHILE_REVALIDATE}`);
271	  }
272	
273	  // Reset scroll position when `isRefetching` becomes `true`.
274	  useEffect(() => {
275	    isRefetching && window.scrollTo(0, 0);
276	    setFiltersLoading(isRefetching);
277	  }, [isRefetching]);
278	
279	  /**************** Render Variables ****************/
280	  const basePath = `${location.pathname}${location.search}`;
281	  const showNoResults = !isLoading && productSearchResult && !productSearchResult?.hits;
282	  const { total, sortingOptions } = productSearchResult || {};
283	  const selectedSortingOptionLabel =
284	    sortingOptions?.find((option) => option.id === productSearchResult?.selectedSortingOption) ?? sortingOptions?.[0];
285	
286	  // Get urls to be used for pagination, page size changes, and sorting.
287	  const pageUrls = usePageUrls({ total });
288	  const sortUrls = useSortUrls({ options: sortingOptions });
289	  const limitUrls = useLimitUrls();
290	
291	  /**************** Action Handlers ****************/
292	  const { data: wishlist } = useWishList();
293	  const addItemToWishlist = async (product: { productId: string }) => {
294	    setWishlistLoading([...wishlistLoading, product.productId]);
295	
296	    // TODO: This wishlist object is from an old API, we need to replace it with the new one.
297	    // `wishlist!`/`customerId!`: this handler only runs from a click on a tile's own wishlist
298	    // toggle, which is only reachable once the page's data has loaded — the original untyped
299	    // JS made the identical assumption implicitly (an undefined `wishlist` here would have
300	    // thrown the same way at runtime); the assertion just makes that pre-existing assumption
301	    // visible instead of introducing a new one.
302	    const listId = wishlist.id;
303	    await createCustomerProductListItem(
304	      {
305	        parameters: { customerId: customerId!, listId },
306	        body: {
307	          quantity: 1,
308	          public: false,
309	          priority: 1,
310	          type: 'product',
311	          productId: product.productId,
312	        },
313	      },
314	      {
315	        onError: () => {
316	          toast({
317	            title: intl.formatMessage(API_ERROR_MESSAGE),
318	            status: 'error',
319	          });
320	        },
321	        onSuccess: () => {
322	          toast({
323	            title: intl.formatMessage(TOAST_MESSAGE_ADDED_TO_WISHLIST, { quantity: 1 }),
324	            status: 'success',
325	            action: (
326	              // it would be better if we could use <Button as={Link}>
327	              // but unfortunately the Link component is not compatible
328	              // with Chakra Toast, since the ToastManager is rendered via portal
329	              // and the toast doesn't have access to intl provider, which is a
330	              // requirement of the Link component.
331	              <Button variant="link" onClick={() => navigate('/account/wishlist')}>
332	                {intl.formatMessage(TOAST_ACTION_VIEW_WISHLIST)}
333	              </Button>
334	            ),
335	          });
336	        },
337	        onSettled: () => {
338	          setWishlistLoading(wishlistLoading.filter((id) => id !== product.productId));
339	        },
340	      },
341	    );
342	  };
343	
344	  const removeItemFromWishlist = async (product: { productId: string }) => {
345	    setWishlistLoading([...wishlistLoading, product.productId]);
346	
347	    // Same reasoning as addItemToWishlist above: only reachable once wishlist data has loaded,
348	    // matching what the original untyped JS already assumed implicitly.
349	    const listId = wishlist.id;
350	    const itemId = wishlist.customerProductListItems!.find(
351	      (i: { productId: string }) => i.productId === product.productId,
352	    )!.id;
353	
354	    await deleteCustomerProductListItem(
355	      {
356	        // No `body` field: the real mutation type has none for a delete, and an empty object
357	        // was never meaningful at runtime either.
358	        parameters: { customerId: customerId!, listId, itemId },
359	      },
360	      {
361	        onError: () => {
362	          toast({
363	            title: intl.formatMessage(API_ERROR_MESSAGE),
364	            status: 'error',
365	          });
366	        },
367	        onSuccess: () => {
368	          toast({
369	            title: intl.formatMessage(TOAST_MESSAGE_REMOVED_FROM_WISHLIST),
370	            status: 'success',
371	          });
372	        },
373	        onSettled: () => {
374	          setWishlistLoading(wishlistLoading.filter((id) => id !== product.productId));
375	        },
376	      },
377	    );
378	  };
379	
380	  // Toggles filter on and off
381	  const toggleFilter = (
382	    value: { value: string | number },
383	    attributeId: string,
384	    selected: boolean,
385	    allowMultiple = true,
386	  ) => {
387	    // Special handling for inventory filter
388	    if (attributeId === 'ilids') {
389	      if (!selected) {
390	        setSearchByInventory(value.value);
391	      } else {
392	        setSearchByInventory(null);
393	      }
394	      return;
395	    }
396	
397	    const searchParamsCopy = { ...searchParams };
398	
399	    // Remove the `offset` search param if present.
400	    delete searchParamsCopy.offset;
401	
402	    // If we aren't allowing for multiple selections, simply clear any value set for the
403	    // attribute, and apply a new one if required.
404	    if (!allowMultiple) {
405	      const previousValue = searchParamsCopy.refine[attributeId];
406	      delete searchParamsCopy.refine[attributeId];
407	
408	      // Note the loose comparison, for "string != number" checks.
409	      if (!selected && value.value != previousValue) {
410	        searchParamsCopy.refine[attributeId] = value.value;
411	      }
412	    } else {
413	      // Get the attibute value as an array.
414	      let attributeValue = searchParamsCopy.refine[attributeId] || [];
415	
416	      // Ensure that the value is still converted into an array if it's a `string` or `number`.
417	      if (typeof attributeValue === 'string') {
418	        attributeValue = attributeValue.split('|');
419	      } else if (typeof attributeValue === 'number') {
420	        attributeValue = [attributeValue];
421	      }
422	
423	      // Either set the value, or filter the value out.
424	      if (!selected) {
425	        attributeValue.push(value.value);
426	      } else {
427	        // Note the loose comparison, for "string != number" checks.
428	        attributeValue = attributeValue?.filter((v: string | number) => v != value.value);
429	      }
430	
431	      // Update the attribute value in the new search params.
432	      searchParamsCopy.refine[attributeId] = attributeValue;
433	
434	      // If the update value is an empty array, remove the current attribute key.
435	      if (searchParamsCopy.refine[attributeId].length === 0) {
436	        delete searchParamsCopy.refine[attributeId];
437	      }
438	    }
439	
440	    if (isSearch) {
441	      navigate(`/search?${stringifySearchParams(searchParamsCopy)}`);
442	    } else {
443	      navigate(`/category/${params.categoryId}?${stringifySearchParams(searchParamsCopy)}`);
444	    }
445	  };
446	
447	  // Clears all filters
448	  const resetFilters = () => {
449	    const newSearchParams = {
450	      ...searchParams,
451	      refine: [],
452	    };
453	    setSearchByInventory(null);
454	    const newPath = isSearch
455	      ? `/search?${stringifySearchParams(newSearchParams)}`
456	      : `/category/${params.categoryId}?${stringifySearchParams(newSearchParams)}`;
457	
458	    navigate(newPath);
459	  };
460	
461	  // Helper function to create StoreInventoryFilter component
462	  const createStoreInventoryFilter = () => {
463	    if (!storeLocatorEnabled) return null;
464	    return (
465	      <StoreInventoryFilter
466	        key="storeInventoryFilter"
467	        toggleFilter={toggleFilter}
468	        selectedFilters={productSearchResult?.selectedRefinements || {}}
469	      />
470	    );
471	  };
472	
473	  /**************** Einstein ****************/
474	  useEffect(() => {
475	    if (productSearchResult) {
476	      if (isSearch) {
477	        try {
478	          einstein.sendViewSearch(searchQuery, productSearchResult);
479	        } catch (err) {
480	          logger.error('Einstein sendViewSearch error', {
481	            namespace: 'ProductList.useEffect',
482	            additionalProperties: { error: err, searchQuery },
483	          });
484	        }
485	        dataCloud.sendViewSearchResults(searchParams, productSearchResult);
486	        activeData.sendViewSearch(searchParams, productSearchResult);
487	      } else {
488	        try {
489	          einstein.sendViewCategory(category, productSearchResult);
490	        } catch (err) {
491	          logger.error('Einstein sendViewCategory error', {
492	            namespace: 'ProductList.useEffect',
493	            additionalProperties: { error: err, category },
494	          });
495	        }
496	        dataCloud.sendViewCategory(searchParams, category, productSearchResult);
497	        activeData.sendViewCategory(searchParams, category, productSearchResult);
498	      }
499	    }
500	  }, [productSearchResult]);
501	
502	  return (
503	    <Box
504	      className="sf-product-list-page"
505	      data-testid="sf-product-list-page"
506	      layerStyle="page"
507	      paddingTop={{ base: 6, lg: 8 }}
508	      {...(rest as BoxProps)}
509	    >
510	      <Helmet>
511	        <title>{category?.pageTitle ?? searchQuery}</title>
512	        <meta name="description" content={category?.pageDescription ?? searchQuery ?? undefined} />
513	        <meta name="keywords" content={category?.pageKeywords} />
514	        {productSearchResult?.pageMetaTags?.map(({ id, value }) => {
515	          return <meta name={id} content={value} key={id} />;
516	        })}
517	      </Helmet>
518	      <>
519	        <AbovePageHeader />
520	        <PageDesignerPromotionalBanner />
521	
522	        {/* Header */}
523	        <Stack
524	          display={{ base: 'none', lg: 'flex' }}
525	          direction="row"
526	          justify="flex-start"
527	          align="flex-start"
528	          spacing={4}
529	          marginBottom={6}
530	        >
531	          <Flex align="left" width="287px">
532	            <PageHeader
533	              searchQuery={searchQuery}
534	              category={category}
535	              productSearchResult={productSearchResult}
536	              isLoading={isLoading}
537	            />
538	          </Flex>
539	
540	          <Box flex={1} paddingTop={'45px'}>
541	            <SelectedRefinements
542	              filters={productSearchResult?.refinements}
543	              toggleFilter={toggleFilter}
544	              handleReset={resetFilters}
545	              selectedFilterValues={productSearchResult?.selectedRefinements}
546	            />
547	          </Box>
548	          <Box paddingTop={'45px'}>
549	            <Sort sortUrls={sortUrls} productSearchResult={productSearchResult} basePath={basePath} />
550	          </Box>
551	        </Stack>
552	
553	        {/* Filter Button for Mobile */}
554	        <HideOnDesktop>
555	          <Stack spacing={6}>
556	            <PageHeader
557	              searchQuery={searchQuery}
558	              category={category}
559	              productSearchResult={productSearchResult}
560	              isLoading={isLoading}
561	            />
562	            <Stack
563	              display={{ base: 'flex', md: 'none' }}
564	              direction="row"
565	              justify="flex-start"
566	              align="center"
567	              spacing={1}
568	              height={12}
569	              borderColor="gray.100"
570	            >
571	              <Flex align="center">
572	                <Button
573	                  fontSize="sm"
574	                  colorScheme="black"
575	                  variant="outline"
576	                  marginRight={2}
577	                  display="inline-flex"
578	                  leftIcon={<FilterIcon boxSize={5} />}
579	                  onClick={onOpen}
580	                >
581	                  <FormattedMessage defaultMessage="Filter" id="product_list.button.filter" />
582	                </Button>
583	              </Flex>
584	              <Flex align="center">
585	                <Button
586	                  maxWidth="245px"
587	                  fontSize="sm"
588	                  marginRight={2}
589	                  colorScheme="black"
590	                  variant="outline"
591	                  display="inline-flex"
592	                  rightIcon={<ChevronDownIcon boxSize={5} />}
593	                  onClick={() => setSortOpen(true)}
594	                >
595	                  {intl.formatMessage(
596	                    {
597	                      id: 'product_list.button.sort_by',
598	                      defaultMessage: 'Sort By: {sortOption}',
599	                    },
600	                    {
601	                      sortOption: selectedSortingOptionLabel?.label,
602	                    },
603	                  )}
604	                </Button>
605	              </Flex>
606	            </Stack>
607	          </Stack>
608	          <Box marginBottom={4}>
609	            <SelectedRefinements
610	              filters={productSearchResult?.refinements}
611	              toggleFilter={toggleFilter}
612	              handleReset={resetFilters}
613	              selectedFilterValues={productSearchResult?.selectedRefinements}
614	            />
615	          </Box>
616	        </HideOnDesktop>
617	
618	        {/* Body  */}
619	        <Grid templateColumns={{ base: '1fr', md: '280px 1fr' }} columnGap={6}>
620	          <Stack display={{ base: 'none', md: 'flex' }}>
621	            <Island hydrateOn={'visible'}>
622	              <Refinements
623	                itemsBefore={
624	                  category?.categories
625	                    ? [
626	                        <CategoryLinks key="itemsBefore" category={category} onSelect={onClose} />,
627	                        createStoreInventoryFilter(),
628	                      ].filter(Boolean)
629	                    : [createStoreInventoryFilter()].filter(Boolean)
630	                }
631	                isLoading={filtersLoading}
632	                toggleFilter={toggleFilter}
633	                filters={productSearchResult?.refinements}
634	                excludedFilters={['cgid']}
635	                selectedFilters={searchParams.refine}
636	              />
637	            </Island>
638	          </Stack>
639	          <Box>
640	            {showNoResults ? (
641	              <EmptySearchResults searchQuery={searchQuery} category={category} />
642	            ) : (
643	              <>
644	                <SimpleGrid columns={[2, 2, 4, 5]} spacingX={4} spacingY={{ base: 12, lg: 16 }}>
645	                  {isHydrated() && ((isRefetching && !isFetched) || !productSearchResult)
646	                    ? new Array(searchParams.limit).fill(0).map((_value, index) => <ProductTileSkeleton key={index} />)
647	                    : productSearchResult?.hits?.map((productSearchItem) => {
648	                        // SFCC-83/84 quick test integration: ZimmProductCard's `plp` variation has
649	                        // no wishlist-toggle affordance at all (only `wishlist` variation has a
650	                        // remove/heart control) — the base ProductTile's `enableFavourite`/
651	                        // `isFavourite`/`onFavouriteToggle` (and the per-item `isInWishlist` lookup
652	                        // that fed it) have no equivalent here, so that per-item computation was
653	                        // removed rather than left dead. `addItemToWishlist`/`removeItemFromWishlist`
654	                        // themselves are untouched above — still there for whenever this affordance
655	                        // gets a real home on this grid.
656	                        const card = selectProductListCard(productSearchItem, formatPrice);
657	                        if (!card) return null;
658	
659	                        const handleAddToBag = () => {
660	                          // `representedProduct?.id`, not the hit's own top-level `productId`
661	                          // directly: for a colour/size-variant product, PLP search hits are
662	                          // represented at the master level, and a master has no SKU — only its
663	                          // variants do (`ShopperSearchTypes.Variant`'s own real SDK doc: "Has a
664	                          // SKU"). `representedProduct` is the SDK's own already-resolved variant
665	                          // reference for this hit; falls back to `productId` for a simple,
666	                          // non-variant product where the two are the same thing anyway.
667	                          const orderableProductId = productSearchItem.representedProduct?.id ?? productSearchItem.productId;
668	                          addItemToNewOrExistingBasket([
669	                            { productId: orderableProductId, price: productSearchItem.price, quantity: 1 },
670	                          ])
671	                            .then(() => toast({ title: intl.formatMessage(messages.addedToBag), status: 'success' }))
672	                            .catch(() => toast({ title: intl.formatMessage(API_ERROR_MESSAGE), status: 'error' }));
673	                        };
674	
675	                        return (
676	                          <Island hydrateOn={'visible'} key={productSearchItem.productId}>
677	                            {/* Wraps rather than passing an onClick prop — ZimmProductCard exposes
678	                                no generic click callback, but a click anywhere in the card (the
679	                                image or the name link) still bubbles up through this wrapper. */}
680	                            <Box
681	                              onClick={() => {
682	                                if (searchQuery) {
683	                                  einstein.sendClickSearch(searchQuery, productSearchItem);
684	                                } else if (category) {
685	                                  einstein.sendClickCategory(category, productSearchItem);
686	                                }
687	                              }}
688	                            >
689	                              <ProductListCard {...card} onAddToBag={handleAddToBag} />
690	                            </Box>
691	                          </Island>
692	                        );
693	                      })}
694	                </SimpleGrid>
695	                {/* Footer */}
696	                <Flex justifyContent={['center', 'center', 'flex-start']} paddingTop={8}>
697	                  <Pagination currentURL={basePath} urls={pageUrls} />
698	
699	                  {/*
700	                Our design doesn't call for a page size select. Show this element if you want
701	                to add one to your design.
702	            */}
703	                  <Select
704	                    display="none"
705	                    value={basePath}
706	                    onChange={({ target }: React.ChangeEvent<HTMLSelectElement>) => {
707	                      history.push(target.value);
708	                    }}
709	                  >
710	                    {limitUrls.map((href: string, index: number) => (
711	                      <option key={href} value={href}>
712	                        {DEFAULT_LIMIT_VALUES[index]}
713	                      </option>
714	                    ))}
715	                  </Select>
716	                </Flex>
717	              </>
718	            )}
719	          </Box>
720	        </Grid>
721	      </>
722	      {/* Modal for filter options on mobile */}
723	      <Modal isOpen={isOpen} onClose={onClose} size="full" motionPreset="slideInBottom" scrollBehavior="inside">
724	        <ModalOverlay />
725	        <ModalContent top={0} marginTop={0}>
726	          <ModalHeader>
727	            <Heading as="h1" fontWeight="bold" fontSize="2xl">
728	              <FormattedMessage defaultMessage="Filter" id="product_list.modal.title.filter" />
729	            </Heading>
730	          </ModalHeader>
731	          <ModalCloseButton />
732	          <ModalBody py={4}>
733	            {filtersLoading && <LoadingSpinner />}
734	            <Refinements
735	              toggleFilter={toggleFilter}
736	              filters={productSearchResult?.refinements}
737	              selectedFilters={searchParams.refine}
738	              itemsBefore={
739	                category?.categories
740	                  ? [
741	                      <CategoryLinks key="itemsBefore" category={category} onSelect={onClose} />,
742	                      createStoreInventoryFilter(),
743	                    ].filter(Boolean)
744	                  : [createStoreInventoryFilter()].filter(Boolean)
745	              }
746	              excludedFilters={['cgid']}
747	            />
748	          </ModalBody>
749	
750	          <ModalFooter
751	            // justify="space-between"
752	            display="block"
753	            width="full"
754	            borderTop="1px solid"
755	            borderColor="gray.100"
756	            paddingBottom={10}
757	          >
758	            <Stack>
759	              <Button width="full" onClick={onClose}>
760	                {intl.formatMessage(
761	                  {
762	                    id: 'product_list.modal.button.view_items',
763	                    defaultMessage: 'View {prroductCount} items',
764	                  },
765	                  {
766	                    prroductCount: productSearchResult?.total,
767	                  },
768	                )}
769	              </Button>
770	              <Button width="full" variant="outline" onClick={resetFilters}>
771	                <FormattedMessage defaultMessage="Clear Filters" id="product_list.modal.button.clear_filters" />
772	              </Button>
773	            </Stack>
774	          </ModalFooter>
775	        </ModalContent>
776	      </Modal>
777	      <Drawer
778	        placement="bottom"
779	        isOpen={sortOpen}
780	        onClose={() => setSortOpen(false)}
781	        size="sm"
782	        motionPreset="slideInBottom"
783	        scrollBehavior="inside"
784	        isFullHeight={false}
785	        height="50%"
786	      >
787	        <DrawerOverlay />
788	        <DrawerContent marginTop={0}>
789	          <DrawerHeader boxShadow="none">
790	            <Text fontWeight="bold" fontSize="2xl">
791	              <FormattedMessage defaultMessage="Sort By" id="product_list.drawer.title.sort_by" />
792	            </Text>
793	          </DrawerHeader>
794	          <DrawerCloseButton />
795	          <DrawerBody>
796	            {sortUrls.map((href: string, idx: number) => (
797	              <Button
798	                width="full"
799	                onClick={() => {
800	                  setSortOpen(false);
801	                  history.push(href);
802	                }}
803	                fontSize={'md'}
804	                key={idx}
805	                marginTop={0}
806	                variant="menu-link"
807	              >
808	                <Text
809	                  as={
810	                    selectedSortingOptionLabel?.label === productSearchResult?.sortingOptions?.[idx]?.label
811	                      ? 'u'
812	                      : undefined
813	                  }
814	                >
815	                  {productSearchResult?.sortingOptions?.[idx]?.label}
816	                </Text>
817	              </Button>
818	            ))}
819	          </DrawerBody>
820	        </DrawerContent>
821	      </Drawer>
822	    </Box>
823	  );
824	};
825	
826	ProductList.getTemplateName = () => 'product-list';
827	
828	export default ProductList;
829	
830	type SortProps = {
831	  sortUrls: string[];
832	  productSearchResult?: { sortingOptions?: { label?: string }[] };
833	  basePath: string;
834	} & Record<string, unknown>;
835	
836	const Sort = ({ sortUrls, productSearchResult, basePath, ...otherProps }: SortProps) => {
837	  const intl = useIntl();
838	  const history = useHistory();
839	
840	  return (
841	    <FormControl
842	      aria-label={intl.formatMessage({
843	        id: 'product_list.drawer.title.sort_by',
844	        defaultMessage: 'Sort By',
845	      })}
846	      data-testid="sf-product-list-sort"
847	      id="page_sort"
848	      width="auto"
849	      {...otherProps}
850	    >
851	      <Select
852	        id="sf-product-list-sort-select"
853	        aria-label={intl.formatMessage({
854	          id: 'product_list.sort_by.label.assistive_msg',
855	          defaultMessage: 'Sort products by',
856	        })}
857	        value={basePath.replace(/(offset)=(\d+)/i, '$1=0')}
858	        onChange={({ target }: React.ChangeEvent<HTMLSelectElement>) => {
859	          history.push(target.value);
860	        }}
861	        height={11}
862	        width="240px"
863	      >
864	        {sortUrls.map((href, index) => (
865	          <option key={href} value={href}>
866	            {intl.formatMessage(
867	              {
868	                id: 'product_list.select.sort_by',
869	                defaultMessage: 'Sort By: {sortOption}',
870	              },
871	              {
872	                sortOption: productSearchResult?.sortingOptions?.[index]?.label,
873	              },
874	            )}
875	          </option>
876	        ))}
877	      </Select>
878	    </FormControl>
879	  );
880	};
