1	/*
2	 * Copyright (c) 2022, Salesforce, Inc.
3	 * All rights reserved.
4	 * SPDX-License-Identifier: BSD-3-Clause
5	 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
6	 */
7	
8	/*
9	 * Copy-first port of
10	 * node_modules/@salesforce/retail-react-app/app/components/recommended-products/index.jsx
11	 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule.
12	 *
13	 * The differences from the base file are the TypeScript annotations below and house
14	 * formatting — no changed JSX, hook calls, prop names, or reordered `useEffect`s, and the base
15	 * file's own dead check (`recommendations.length < 1` on what is always an object) is ported
16	 * byte-identical in behaviour. The annotations: a `RecommendedProductsProps` type replacing the
17	 * `propTypes` block; a narrow local `RecommendedProduct` type for the one field read off a
18	 * recommendation-context product (reused for the `productTileProps` callback's own `product`
19	 * param below, since it is that same recommendation-context product); an explicit `boolean`
20	 * param on the one nested callback that isn't contextually typed; and inline
21	 * `{ productId?: string }` / `{ id?: string }` object-type-literal params on four
22	 * `.find`/`.some`/`.map` callbacks whose containing expression is untyped (`any`) and therefore
23	 * supplies no contextual parameter type — `noImplicitAny` flags these regardless of the `any`
24	 * receiver (confirmed against `npx tsc --noEmit`, which is why these four are annotated despite
25	 * this file's own initial plan expecting two of them not to need it). The `{ productId?: string
26	 * }` shape and inline-annotation style mirrors the existing precedent at
27	 * product-detail/index.tsx:437 and :735; the `{ id?: string }` shape matches the field the base
28	 * hook itself reads, `use-einstein.js`'s own `reco.recs?.map((rec) => rec.id)` (line 466).
29	 *
30	 * A sixth adjustment, found by lint rather than tsc: the base file destructures `formatMessage`
31	 * straight off `useIntl()`, but `@typescript-eslint/unbound-method` flags any destructured
32	 * reference to it — `formatMessage` is declared with method-shorthand syntax in
33	 * `@formatjs/intl/src/types.d.ts:64-65`, which this rule always flags regardless of whether the
34	 * real implementation needs `this`. Fix: keep the whole object (`const intl = useIntl();`) and
35	 * call `intl.formatMessage(...)` at each of its five call sites instead of destructuring — a
36	 * property-access call sidesteps the rule entirely, with zero behavioural change. Same
37	 * "toolchain requires a different access shape than the untyped base file used" reasoning as the
38	 * annotations above.
39	 *
40	 * SFCC-83/84 build plan step A6 (2026-09-07) adds one branch: when `recommender ===
41	 * EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED` (`'viewed-recently-einstein'`, the same string
42	 * `CART_RECENTLY_VIEWED` resolves to — confirmed identical in
43	 * node_modules/@salesforce/retail-react-app/app/constants.js:154-160), `recommendations.recs`
44	 * maps through `selectRecentlyViewedCard` (overrides/app/utils/recentlyViewedCard.ts) and renders
45	 * `ZimmRecentlyViewedRail` instead, gated by `useRecentlyViewedGate`
46	 * (overrides/app/hooks/useRecentlyViewedGate.ts). Every other recommender keeps the original
47	 * `ProductScroller` branch below, untouched.
48	 *
49	 * `ref` is still attached on the Recently Viewed branch too, via a plain wrapping `<Box
50	 * ref={ref}>` — `isOnScreen` below (the impression-tracking gate for `sendViewReco`/
51	 * `dataCloud.sendViewRecommendations`) only works once `ref.current` is a real DOM node
52	 * (use-intersection-observer.js: `if (!ref?.current) return`, with no dependency on which
53	 * component produced that node), and `ZimmRecentlyViewedRail` is a plain function component with
54	 * no `forwardRef` support of its own. Wrapping here, rather than adding `forwardRef` to that
55	 * already-committed component (A5), keeps this fix entirely inside this file.
56	 *
57	 * `headingLevel`/`variation` are added here, not by the mapper: `selectRecentlyViewedCard`'s own
58	 * docblock states both are deliberately excluded from its output because they are this
59	 * container's decision to make. `headingLevel: 'h3'` is inert for this variation —
60	 * `ZimmProductCardContent` never mounts when `variation: 'recentlyViewed'`
61	 * (zimmProductCard/index.tsx's `VARIATION_CONFIG.showContent`) — and matches the one other
62	 * established value for this same required field (product-list/productListCardMapper.ts).
63	 *
64	 * `{...props}` is forwarded to the `<Box>` wrapper (cast to `BoxProps` — this file's own index
65	 * signature types `props` as `Record<string, unknown>`, not safely spreadable onto `Box`'s typed
66	 * props otherwise), matching the ProductScroller branch below exactly. This matters concretely:
67	 * PDP passes `mx={{base: -4, md: -8, lg: 0}}` and Cart passes `mx={{base: -4, sm: -6, lg: 0}}` to
68	 * bleed this component edge-to-edge on mobile/tablet — without forwarding it, this branch would
69	 * render inset inside the page's normal content padding while every sibling rail on the same page
70	 * bleeds to the edge, and `zimmRecentlyViewedRail.css.ts`'s own card-width math (e.g. 201x2=402)
71	 * assumes the full viewport width is actually available. Still worth a live look on PDP/Cart —
72	 * this closes the gap structurally but wasn't visually confirmed in a running browser.
73	 */
74	
75	import React, { useEffect, useRef, useState } from 'react';
76	import type { ReactNode } from 'react';
77	import { useIntl } from 'react-intl';
78	import type { BoxProps } from '@chakra-ui/react';
79	import { Box, Button } from '@salesforce/retail-react-app/app/components/shared/ui';
80	import ProductScroller from '@salesforce/retail-react-app/app/components/product-scroller';
81	import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
82	import useDataCloud from '@salesforce/retail-react-app/app/hooks/use-datacloud';
83	import { useCurrentCustomer } from '@salesforce/retail-react-app/app/hooks/use-current-customer';
84	import useIntersectionObserver from '@salesforce/retail-react-app/app/hooks/use-intersection-observer';
85	import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';
86	
87	import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
88	import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
89	import {
90	  API_ERROR_MESSAGE,
91	  EINSTEIN_RECOMMENDERS,
92	  TOAST_ACTION_VIEW_WISHLIST,
93	  TOAST_MESSAGE_ADDED_TO_WISHLIST,
94	  TOAST_MESSAGE_REMOVED_FROM_WISHLIST,
95	} from '@salesforce/retail-react-app/app/constants';
96	import { useShopperCustomersMutation } from '@salesforce/commerce-sdk-react';
97	// Relative, not the base package path — .claude/rules/overrideStyling.md's "Importing an
98	// already-overridden component from a new component": .storybook/main.js and vitest.config.ts
99	// don't load the overrides resolver, so a base-path import here would silently story/test the
100	// unstyled base component instead of this override.
101	import { ZimmRecentlyViewedRail } from '../ui-kits/organisms/zimmRecentlyViewedRail';
102	import type { ZimmProductCardProps } from '../ui-kits/organisms/zimmProductCard';
103	import { selectRecentlyViewedCard } from '../../utils/recentlyViewedCard';
104	import type { RecentlyViewedProduct, RecentlyViewedCard } from '../../utils/recentlyViewedCard';
105	import { useRecentlyViewedGate } from '../../hooks/useRecentlyViewedGate';
106	
107	/**
108	 * The one field this file reads off a recommendation-context product. A real
109	 * commerce-sdk-isomorphic Product shape underlies it, but @salesforce/retail-react-app's
110	 * useEinstein/ProductScroller ship untyped (vendor.d.ts's wildcard), so this is narrowed
111	 * to exactly the field touched here rather than invented more broadly (AGENTS.md > Type
112	 * Definitions: hand-roll only the genuinely unexported shape actually used).
113	 */
114	type RecommendedProduct = { productId?: string };
115	
116	export type RecommendedProductsProps = {
117	  /* The title to appear above the product scroller */
118	  title?: ReactNode;
119	
120	  /* The zone to request */
121	  zone?: string;
122	
123	  /* The recommender to request */
124	  recommender?: string;
125	
126	  /* The products to use for recommendation context */
127	  products?: readonly Record<string, unknown>[];
128	
129	  /* Callback to determine if the component should fetch results */
130	  shouldFetch?: () => boolean;
131	
132	  // Index signature for the `...props` passthrough to ProductScroller (itself untyped — see
133	  // vendor.d.ts). Without it, the destructured rest types as `{}` instead of accepting arbitrary
134	  // passthrough, which is the base file's actual intent: forwarding whatever else the caller
135	  // passes.
136	  [key: string]: unknown;
137	};
138	
139	/**
140	 * A component for fetching and rendering product recommendations from the Einstein API
141	 * by a zone or a recommender name.
142	 */
143	const RecommendedProducts = ({
144	  zone,
145	  recommender,
146	  products,
147	  title,
148	  shouldFetch,
149	  ...props
150	}: RecommendedProductsProps) => {
151	  const { isLoading, recommendations, getZoneRecommendations, getRecommendations, sendClickReco, sendViewReco } =
152	    useEinstein();
153	  const { data: customer } = useCurrentCustomer();
154	  const { customerId } = customer;
155	  const { data: wishlist } = useWishList();
156	  const dataCloud = useDataCloud();
157	
158	  const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');
159	  const deleteCustomerProductListItem = useShopperCustomersMutation('deleteCustomerProductListItem');
160	  const toast = useToast();
161	  const navigate = useNavigation();
162	  const intl = useIntl();
163	  // Same split product-list/productListCardMapper.ts's own consumer uses
164	  // (product-list/index.tsx): passed into the mapper rather than formatted there, keeping that
165	  // mapper free of any react-intl dependency of its own.
166	  const formatPrice = (amount: number, currency: string) => intl.formatNumber(amount, { style: 'currency', currency });
167	
168	  const ref = useRef();
169	  const isOnScreen = useIntersectionObserver(ref, { useOnce: true });
170	  const [_products, setProducts] = useState(products);
171	  // Unconditional, alongside the hook calls above — must run on every render, including the
172	  // ones that hit the dead-code early return two blocks below, per React's rules of hooks.
173	  const hasRecentlyViewed = useRecentlyViewedGate();
174	
175	  useEffect(() => {
176	    // Check if the component should fetch results or not. This is useful
177	    // when you are still waiting on additional data, like `products`.
178	    if (typeof shouldFetch === 'function' && !shouldFetch()) {
179	      return;
180	    }
181	
182	    // Fetch either zone or recommender, but not both. If a zone and recommender
183	    // name are both provided, `zone` takes precendence.
184	    if (zone) {
185	      getZoneRecommendations(zone, _products);
186	      return;
187	    }
188	    if (recommender) {
189	      getRecommendations(recommender, _products);
190	      return;
191	    }
192	  }, [zone, recommender, _products]);
193	
194	  useEffect(() => {
195	    // This is an optimization that eliminates superfluous rerenders/fetching by
196	    // keeping a copy of the `products` array prop in state for shallow comparison.
197	    if (!Array.isArray(products)) {
198	      return;
199	    }
200	    if (products.length !== _products?.length || !products.every((val, index) => val === _products?.[index])) {
201	      setProducts(products);
202	    }
203	  }, [products]);
204	
205	  useEffect(() => {
206	    if (isOnScreen && recommendations?.recs) {
207	      sendViewReco(
208	        {
209	          recommenderName: recommendations.recommenderName,
210	          __recoUUID: recommendations.recoUUID,
211	        },
212	        recommendations.recs.map((rec: { id?: string }) => ({ id: rec.id })),
213	      );
214	      dataCloud.sendViewRecommendations(
215	        {
216	          recommenderName: recommendations.recommenderName,
217	          __recoUUID: recommendations.recoUUID,
218	        },
219	        recommendations.recs.map((rec: { id?: string }) => ({ id: rec.id })),
220	      );
221	    }
222	  }, [isOnScreen, recommendations]);
223	
224	  // The component should remove itself altogether if it has no recommendations
225	  // and we aren't loading any.
226	  if (!isLoading && (!recommendations || recommendations.length < 1)) {
227	    return null;
228	  }
229	
230	  // TODO: DRY this handler when intl provider is available globally
231	  const addItemToWishlist = async (product: RecommendedProduct) => {
232	    try {
233	      if (!wishlist || !customerId) {
