252	        status: 'success',
253	        action: (
254	          // it would be better if we could use <Button as={Link}>
255	          // but unfortunately the Link component is not compatible
256	          // with Chakra Toast, since the ToastManager is rendered via portal
257	          // and the toast doesn't have access to intl provider, which is a
