312	    const cards: ZimmProductCardProps[] = (recommendations?.recs ?? [])
313	      .map((rec: RecentlyViewedProduct) => selectRecentlyViewedCard(rec, formatPrice))
314	      .filter((card: RecentlyViewedCard | null): card is RecentlyViewedCard => card !== null)
315	      .map(
316	        (card: RecentlyViewedCard): ZimmProductCardProps => ({
317	          ...card,
