/*
 * Copy-first port of
 * node_modules/@salesforce/retail-react-app/app/components/recommended-products/index.jsx
 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule.
 *
 * The differences from the base file are the TypeScript annotations below and house
 * formatting — no changed JSX, hook calls, prop names, or reordered `useEffect`s, and the base
 * file's own dead check (`recommendations.length < 1` on what is always an object) is ported
 * byte-identical in behaviour. The annotations: a `RecommendedProductsProps` type replacing the
 * `propTypes` block; a narrow local `RecommendedProduct` type for the one field read off a
 * recommendation-context product (reused for the `productTileProps` callback's own `product`
 * param below, since it is that same recommendation-context product); an explicit `boolean`
 * param on the one nested callback that isn't contextually typed; and inline
 * `{ productId?: string }` / `{ id?: string }` object-type-literal params on four
 * `.find`/`.some`/`.map` callbacks whose containing expression is untyped (`any`) and therefore
 * supplies no contextual parameter type — `noImplicitAny` flags these regardless of the `any`
 * receiver (confirmed against `npx tsc --noEmit`, which is why these four are annotated despite
 * this file's own initial plan expecting two of them not to need it). The `{ productId?: string
 * }` shape and inline-annotation style mirrors the existing precedent at
 * product-detail/index.tsx:437 and :735; the `{ id?: string }` shape matches the field the base
 * hook itself reads, `use-einstein.js`'s own `reco.recs?.map((rec) => rec.id)` (line 466).
 *
 * A sixth adjustment, found by lint rather than tsc: the base file destructures `formatMessage`
 * straight off `useIntl()`, but `@typescript-eslint/unbound-method` flags any destructured
 * reference to it — `formatMessage` is declared with method-shorthand syntax in
 * `@formatjs/intl/src/types.d.ts:64-65`, which this rule always flags regardless of whether the
 * real implementation needs `this`. Fix: keep the whole object (`const intl = useIntl();`) and
 * call `intl.formatMessage(...)` at each of its five call sites instead of destructuring — a
 * property-access call sidesteps the rule entirely, with zero behavioural change. Same
 * "toolchain requires a different access shape than the untyped base file used" reasoning as the
 * annotations above.
 *
 * SFCC-83/84 build plan step A6 (2026-09-07) adds one branch: when `recommender ===
 * EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED` (`'viewed-recently-einstein'`, the same string
 * `CART_RECENTLY_VIEWED` resolves to — confirmed identical in
 * node_modules/@salesforce/retail-react-app/app/constants.js:154-160), `recommendations.recs`
 * maps through `selectRecentlyViewedCard` (overrides/app/utils/recentlyViewedCard.ts) and renders
 * `ZimmRecentlyViewedRail` instead, gated by `useRecentlyViewedGate`
 * (overrides/app/hooks/useRecentlyViewedGate.ts). Every other recommender keeps the original
 * `ProductScroller` branch below, untouched.
 *
 * `ref` is still attached on the Recently Viewed branch too, via a plain wrapping `<Box
 * ref={ref}>` — `isOnScreen` below (the impression-tracking gate for `sendViewReco`/
 * `dataCloud.sendViewRecommendations`) only works once `ref.current` is a real DOM node
 * (use-intersection-observer.js: `if (!ref?.current) return`, with no dependency on which
 * component produced that node), and `ZimmRecentlyViewedRail` is a plain function component with
 * no `forwardRef` support of its own. Wrapping here, rather than adding `forwardRef` to that
 * already-committed component (A5), keeps this fix entirely inside this file.
 *
 * `headingLevel`/`variation` are added here, not by the mapper: `selectRecentlyViewedCard`'s own
 * docblock states both are deliberately excluded from its output because they are this
 * container's decision to make. `headingLevel: 'h3'` is inert for this variation —
 * `ZimmProductCardContent` never mounts when `variation: 'recentlyViewed'`
 * (zimmProductCard/index.tsx's `VARIATION_CONFIG.showContent`) — and matches the one other
 * established value for this same required field (product-list/productListCardMapper.ts).
 *
 * `{...props}` is forwarded to the `<Box>` wrapper (cast to `BoxProps` — this file's own index
 * signature types `props` as `Record<string, unknown>`, not safely spreadable onto `Box`'s typed
 * props otherwise), matching the ProductScroller branch below exactly. This matters concretely:
 * PDP passes `mx={{base: -4, md: -8, lg: 0}}` and Cart passes `mx={{base: -4, sm: -6, lg: 0}}` to
 * bleed this component edge-to-edge on mobile/tablet — without forwarding it, this branch would
 * render inset inside the page's normal content padding while every sibling rail on the same page
 * bleeds to the edge, and `zimmRecentlyViewedRail.css.ts`'s own card-width math (e.g. 201x2=402)
 * assumes the full viewport width is actually available. Still worth a live look on PDP/Cart —
 * this closes the gap structurally but wasn't visually confirmed in a running browser.
 */

import React, { useEffect, useRef, useState } from 'react';
import type { ReactNode } from 'react';
import { useIntl } from 'react-intl';
import type { BoxProps } from '@chakra-ui/react';
import { Box, Button } from '@salesforce/retail-react-app/app/components/shared/ui';
import ProductScroller from '@salesforce/retail-react-app/app/components/product-scroller';
import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
import useDataCloud from '@salesforce/retail-react-app/app/hooks/use-datacloud';
import { useCurrentCustomer } from '@salesforce/retail-react-app/app/hooks/use-current-customer';
import useIntersectionObserver from '@salesforce/retail-react-app/app/hooks/use-intersection-observer';
import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';

import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
import {
  API_ERROR_MESSAGE,
  EINSTEIN_RECOMMENDERS,
  TOAST_ACTION_VIEW_WISHLIST,
  TOAST_MESSAGE_ADDED_TO_WISHLIST,
  TOAST_MESSAGE_REMOVED_FROM_WISHLIST,
} from '@salesforce/retail-react-app/app/constants';
import { useShopperCustomersMutation } from '@salesforce/commerce-sdk-react';
// Relative, not the base package path — .claude/rules/overrideStyling.md's "Importing an
// already-overridden component from a new component": .storybook/main.js and vitest.config.ts
// don't load the overrides resolver, so a base-path import here would silently story/test the
// unstyled base component instead of this override.
import { ZimmRecentlyViewedRail } from '../ui-kits/organisms/zimmRecentlyViewedRail';
import type { ZimmProductCardProps } from '../ui-kits/organisms/zimmProductCard';
import { selectRecentlyViewedCard } from '../../utils/recentlyViewedCard';
import type { RecentlyViewedProduct, RecentlyViewedCard } from '../../utils/recentlyViewedCard';
import { useRecentlyViewedGate } from '../../hooks/useRecentlyViewedGate';

/**
 * The one field this file reads off a recommendation-context product. A real
 * commerce-sdk-isomorphic Product shape underlies it, but @salesforce/retail-react-app's
 * useEinstein/ProductScroller ship untyped (vendor.d.ts's wildcard), so this is narrowed
 * to exactly the field touched here rather than invented more broadly (AGENTS.md > Type
 * Definitions: hand-roll only the genuinely unexported shape actually used).
 */
type RecommendedProduct = { productId?: string };

export type RecommendedProductsProps = {
  /* The title to appear above the product scroller */
  title?: ReactNode;

  /* The zone to request */
  zone?: string;

  /* The recommender to request */
  recommender?: string;

  /* The products to use for recommendation context */
  products?: readonly Record<string, unknown>[];

  /* Callback to determine if the component should fetch results */
  shouldFetch?: () => boolean;

  // Index signature for the `...props` passthrough to ProductScroller (itself untyped — see
  // vendor.d.ts). Without it, the destructured rest types as `{}` instead of accepting arbitrary
  // passthrough, which is the base file's actual intent: forwarding whatever else the caller
  // passes.
  [key: string]: unknown;
};

/**
 * A component for fetching and rendering product recommendations from the Einstein API
 * by a zone or a recommender name.
 */
const RecommendedProducts = ({
  zone,
  recommender,
  products,
  title,
  shouldFetch,
  ...props
}: RecommendedProductsProps) => {
  const { isLoading, recommendations, getZoneRecommendations, getRecommendations, sendClickReco, sendViewReco } =
    useEinstein();
  const { data: customer } = useCurrentCustomer();
  const { customerId } = customer;
  const { data: wishlist } = useWishList();
  const dataCloud = useDataCloud();

  const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');
  const deleteCustomerProductListItem = useShopperCustomersMutation('deleteCustomerProductListItem');
  const toast = useToast();
  const navigate = useNavigation();
  const intl = useIntl();
  // Same split product-list/productListCardMapper.ts's own consumer uses
  // (product-list/index.tsx): passed into the mapper rather than formatted there, keeping that
  // mapper free of any react-intl dependency of its own.
  const formatPrice = (amount: number, currency: string) => intl.formatNumber(amount, { style: 'currency', currency });

  const ref = useRef();
  const isOnScreen = useIntersectionObserver(ref, { useOnce: true });
  const [_products, setProducts] = useState(products);
  // Unconditional, alongside the hook calls above — must run on every render, including the
  // ones that hit the dead-code early return two blocks below, per React's rules of hooks.
  const hasRecentlyViewed = useRecentlyViewedGate();

  useEffect(() => {
    // Check if the component should fetch results or not. This is useful
    // when you are still waiting on additional data, like `products`.
    if (typeof shouldFetch === 'function' && !shouldFetch()) {
      return;
    }

    // Fetch either zone or recommender, but not both. If a zone and recommender
    // name are both provided, `zone` takes precendence.
    if (zone) {
      getZoneRecommendations(zone, _products);
      return;
    }
    if (recommender) {
      getRecommendations(recommender, _products);
      return;
    }
  }, [zone, recommender, _products]);

  useEffect(() => {
    // This is an optimization that eliminates superfluous rerenders/fetching by
    // keeping a copy of the `products` array prop in state for shallow comparison.
    if (!Array.isArray(products)) {
      return;
    }
    if (products.length !== _products?.length || !products.every((val, index) => val === _products?.[index])) {
      setProducts(products);
    }
  }, [products]);

  useEffect(() => {
    if (isOnScreen && recommendations?.recs) {
      sendViewReco(
        {
          recommenderName: recommendations.recommenderName,
          __recoUUID: recommendations.recoUUID,
        },
        recommendations.recs.map((rec: { id?: string }) => ({ id: rec.id })),
      );
      dataCloud.sendViewRecommendations(
        {
          recommenderName: recommendations.recommenderName,
          __recoUUID: recommendations.recoUUID,
        },
        recommendations.recs.map((rec: { id?: string }) => ({ id: rec.id })),
      );
    }
  }, [isOnScreen, recommendations]);

  // The component should remove itself altogether if it has no recommendations
  // and we aren't loading any.
  if (!isLoading && (!recommendations || recommendations.length < 1)) {
    return null;
  }

  // TODO: DRY this handler when intl provider is available globally
  const addItemToWishlist = async (product: RecommendedProduct) => {
    try {
      if (!wishlist || !customerId) {
        return;
      }
      await createCustomerProductListItem.mutateAsync({
        parameters: {
          listId: wishlist.id,
          customerId,
        },
        body: {
          quantity: 1,
          productId: product.productId,
          public: false,
          priority: 1,
          type: 'product',
        },
      });

      toast({
        title: intl.formatMessage(TOAST_MESSAGE_ADDED_TO_WISHLIST, { quantity: 1 }),
        status: 'success',
        action: (
          // it would be better if we could use <Button as={Link}>
          // but unfortunately the Link component is not compatible
          // with Chakra Toast, since the ToastManager is rendered via portal
          // and the toast doesn't have access to intl provider, which is a
          // requirement of the Link component.
          <Button variant="link" onClick={() => navigate('/account/wishlist')}>
            {intl.formatMessage(TOAST_ACTION_VIEW_WISHLIST)}
          </Button>
        ),
      });
    } catch {
      toast({
        title: intl.formatMessage(API_ERROR_MESSAGE),
        status: 'error',
      });
    }
  };

  const removeItemFromWishlist = async (product: RecommendedProduct) => {
    try {
      const wishlistItem = wishlist?.customerProductListItems?.find(
        (item: { productId?: string }) => item.productId === product.productId,
      );
      if (!wishlistItem || !wishlist || !customerId) {
        return;
      }
      await deleteCustomerProductListItem.mutateAsync({
        parameters: {
          customerId,
          itemId: wishlistItem.id,
          listId: wishlist.id,
        },
      });
      toast({
        title: intl.formatMessage(TOAST_MESSAGE_REMOVED_FROM_WISHLIST),
        status: 'success',
        id: product.productId,
      });
    } catch {
      toast({
        title: intl.formatMessage(API_ERROR_MESSAGE),
        status: 'error',
      });
    }
  };

  // SFCC-83 — Recently Viewed only. Every other recommender falls through to the unchanged
  // ProductScroller branch below.
  if (recommender === EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED) {
    // AC 8's empty-state gate — see useRecentlyViewedGate.ts's own docblock. No rail, no title,
    // no placeholder.
    if (!hasRecentlyViewed) {
      return null;
    }

    // `recommendations` is untyped (`any` — see this file's own module docblock), so, matching
    // the pre-existing `.find`/`.some`/`.map` callbacks above, every step of this chain needs an
    // explicit parameter type: `noImplicitAny` flags each one regardless of the `any` receiver.
    const cards: ZimmProductCardProps[] = (recommendations?.recs ?? [])
      .map((rec: RecentlyViewedProduct) => selectRecentlyViewedCard(rec, formatPrice))
      .filter((card: RecentlyViewedCard | null): card is RecentlyViewedCard => card !== null)
      .map(
        (card: RecentlyViewedCard): ZimmProductCardProps => ({
          ...card,
          // Inert for this variation — ZimmProductCardContent never mounts when
          // variation: 'recentlyViewed' (zimmProductCard/index.tsx's
          // VARIATION_CONFIG.showContent). 'h3' matches the one other established value for
          // this same required field (product-list/productListCardMapper.ts).
          headingLevel: 'h3',
          variation: 'recentlyViewed',
        }),
      );

    return (
      // Ref-attachment point — see the module docblock's own isOnScreen/forwardRef note above for
      // why this wrapper exists at all. `{...props}` forwards the caller's own layout props (e.g.
      // PDP's `mx={{base: -4, md: -8, lg: 0}}`, Cart's `mx={{base: -4, sm: -6, lg: 0}}`) exactly
      // as the ProductScroller branch below already does — without it, this branch would render
      // inset inside the page's normal content padding while every sibling rail on the same page
      // bleeds edge-to-edge, and zimmRecentlyViewedRail.css.ts's own card-width math (e.g.
      // 201x2=402) assumes the full viewport width is actually available.
      <Box ref={ref} {...(props as BoxProps)}>
        <ZimmRecentlyViewedRail title={title || recommendations?.displayMessage} cards={cards} />
      </Box>
    );
  }

  return (
    <ProductScroller
      ref={ref}
      title={title || recommendations?.displayMessage}
      products={recommendations.recs}
      isLoading={isLoading}
      productTileProps={(product: RecommendedProduct) => ({
        onClick: () => {
          sendClickReco(
            {
              recommenderName: recommendations.recommenderName,
              __recoUUID: recommendations.recoUUID,
            },
            product,
          );
        },
        enableFavourite: true,
        isFavourite: wishlist?.customerProductListItems?.some(
          (item: { productId?: string }) => item.productId === product?.productId,
        ),
        onFavouriteToggle: (toBeFavourite: boolean) => {
          const action = toBeFavourite ? addItemToWishlist : removeItemFromWishlist;
          return action(product);
        },
      })}
      {...props}
    />
  );
};

export default RecommendedProducts;

import React from 'react';
import type { ReactNode } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { Link as RouteLink } from 'react-router-dom';
import { RECENTLY_VIEWED_RAIL_MAX_ITEMS } from 'app/constants';
import { ZimmProductCard } from '../zimmProductCard';
import type { ZimmProductCardProps } from '../zimmProductCard';

// Same `chakra(RouteLink)` wrap this component family already establishes for its own internal
// links (zimmProductCard/index.tsx's `MediaOnlyCardLink`, zimmProductCardContent/index.tsx's
// `ProductNameLink`) — used here for the See-Full-History link, which navigates to the SFCC-84
// Recently Viewed Full History page, an internal route, not an external URL.
const SeeAllLink = chakra(RouteLink);

export type ZimmRecentlyViewedRailProps = {
  /**
   * Typed as `ReactNode`, not `string` — this component owns no copy/intl (the container, A6,
   * does). **Styling resolved 2026-09-08** (was previously left unstyled pending confirmation —
   * live Storybook testing caught the resulting bug: the title rendered in the ambient body
   * weight, Futura Round 400, instead of the design's intended weight): this component now
   * applies `textStyle="heading3"` itself when rendering `title`, matching the exact spec
   * confirmed against the Full History page's own title bar this same session (Figma
   * `Default/h3-strong` — Futura Round, 16px/18 line-height, weight 500, letter-spacing -0.12px,
   * uppercase — cross-checked against this codebase's registered `heading3` token, an exact
   * match). Applying it here rather than requiring every caller to pre-style the title guarantees
   * the design intent regardless of what a caller passes; a caller supplying an already fully
   * styled element can still override any of this via its own more-specific styling.
   */
  title: ReactNode;
  /**
   * Rendered in the exact order received (AC 2: most-recent-first, left to right) — no sorting or
   * reordering happens here. Capped to `RECENTLY_VIEWED_RAIL_MAX_ITEMS` regardless of length; see
   * that constant's own comment (app/constants/index.ts) for why the cap has to live here rather
   * than in the request that produced this array.
   */
  cards: readonly ZimmProductCardProps[];
  /** Href to the SFCC-84 Recently Viewed Full History page. The See-Full-History link only
   *  renders when this is provided — see the render body below. */
  seeAllHref?: string;
  /**
   * No default/fallback text is supplied when this is omitted while `seeAllHref` is provided —
   * this component owns no copy or intl (see the module docblock), so inventing an English
   * fallback here would risk shipping untranslated text on non-English storefronts. In real usage
   * the container (A6) is expected to always supply this alongside `seeAllHref`.
   */
  seeAllLabel?: string;
};

const ZIMM_RECENTLY_VIEWED_RAIL_RECIPE = 'ZimmRecentlyViewedRail';

/**
 * SFCC-83 — the Recently Viewed rail organism (build plan section A5). Purely presentational:
 * data arrives as props, no data-fetching, no `useEinstein`, no `useIntl` — see
 * .claude/rules/components.md's container/presentational split. The container (A6) is
 * responsible for building `cards` (via A3's Einstein-rec-to-card mapper), gating this
 * component's visibility (A4's `hasRecentlyViewed`), and supplying `title`/`seeAllLabel` copy.
 *
 * Structure mirrors Figma exactly: a `header` row (title left, the See-Full-History link right)
 * above a horizontally scrollable `group` of `ZimmProductCard`s. No rail-level arrow buttons —
 * `ZimmProductCardMedia` already carries its own intra-card carousel arrows, and a second set at
 * the rail level would collide with them (see zimmRecentlyViewedRail.css.ts's own docblock for
 * the Figma node evidence). Paging is native horizontal scroll with CSS scroll-snap only.
 *
 * `cards` is typed as the full `ZimmProductCardProps` union, matching this step's own given
 * component contract verbatim — this component therefore spreads each entry straight into
 * `ZimmProductCard` (`<ZimmProductCard {...card} />`) rather than forcing
 * `variation: 'recentlyViewed'` onto every card itself. In real usage every entry already carries
 * that variation by construction (A3's mapper produces `recentlyViewed`-shaped cards, matching
 * `variation: 'recentlyViewed'` in the type union — see zimmProductCard/index.tsx's
 * `ZimmProductCardRecentlyViewedVariation`) — this component trusts that contract rather than
 * re-asserting it, consistent with staying purely presentational.
 *
 * `data-testid="product-card"` / `data-product-id` on each rendered card come from
 * `ZimmProductCard`'s own root (zimmProductCard/index.tsx: "a DOM hook for QA automation/
 * analytics") — this component adds no additional per-card test hook of its own.
 */
export const ZimmRecentlyViewedRail = ({ title, cards, seeAllHref, seeAllLabel }: ZimmRecentlyViewedRailProps) => {
  const styles = useMultiStyleConfig(ZIMM_RECENTLY_VIEWED_RAIL_RECIPE, {});

  // Cap is enforced here, client-side, regardless of how many cards were passed in — see
  // RECENTLY_VIEWED_RAIL_MAX_ITEMS's own comment (app/constants/index.ts): the Einstein API this
  // data ultimately comes from does not itself honour a requested limit. A slice, never a sort —
  // order is otherwise untouched (AC 2).
  const visibleCards = cards.slice(0, RECENTLY_VIEWED_RAIL_MAX_ITEMS);

  // Second guard behind A4's own visibility gate, which lives in the container, not here — an
  // empty rail renders nothing at all, not an empty shell.
  if (visibleCards.length === 0) {
    return null;
  }

  return (
    <chakra.div __css={styles.container} data-testid="recently-viewed-rail">
      <chakra.div __css={styles.header}>
        <chakra.span textStyle="heading3">{title}</chakra.span>
        {seeAllHref && (
          <SeeAllLink to={seeAllHref} textStyle="linkLg" __css={styles.seeAllLink}>
            {seeAllLabel}
          </SeeAllLink>
        )}
      </chakra.div>
      <chakra.div __css={styles.group} data-testid="recently-viewed-rail-group">
        {visibleCards.map((card) => (
          <chakra.div key={card.id} __css={styles.card}>
            <ZimmProductCard {...card} />
          </chakra.div>
        ))}
      </chakra.div>
    </chakra.div>
  );
};

import type { SystemStyleObject } from '@chakra-ui/react';
import { breakpoints } from 'app/theme/foundation';

/**
 * Recipe for the Recently Viewed rail organism (SFCC-83), build plan section A5. Figma component
 * set `40000587:38471` — Desktop `40000307:12444` (1440x528), Tablet `40000730:13363`
 * (768x437.85), Mobile `40000538:25030` (402x355.82). The Figma decomposition confirmed by the
 * build plan is exactly two children — `title-and-link` and `group`, no arrow layer (a rail-level
 * carousel would collide with ZimmProductCardMedia's own intra-card arrows) — mapped onto `header`
 * and `group` below. Two more parts exist that have no Figma layer of their own: `seeAllLink`
 * (the See-Full-History link's colour/hover/focus states) and `card` (each card's own
 * per-breakpoint fixed width — ZimmProductCard's own root has no width opinion, see index.tsx).
 * `container` is the outermost wrapper, deliberately not named `root`: this recipe's own outer
 * part and the composed ZimmProductCard's own `root` part (zimmProductCard.css.ts) are unrelated
 * recipes that would otherwise both want the same name.
 *
 * CARD WIDTH — three explicit breakpoints, real Figma values (per this step's own brief, read
 * 2026-09-06): 201px / 256px / 288px at Mobile / Tablet / Desktop respectively. None of these has
 * an existing --zimm-scale-* equivalent — checked against every numeric alias in zimmTokens.ts,
 * the scale runs ...48, 52, 64, 140, 180... with nothing between 52 and 64 or between 64 and 140 —
 * so all three are named constants below carrying an explicit pending-token comment, per
 * .claude/rules/overrideStyling.md's "Never" note. Expressed in rem, not px: matches this repo's
 * own established precedent for a *sizing* (not hairline) dimension with no foundation token yet
 * — footer.css.ts's SIZE_COL_SUB / SIZE_COL_MAP (footer column widths) use the identical
 * rem-with-pending-comment shape for the same reason (overrideStyling.md's Units section: rem is
 * for anything that should scale with root font-size/zoom per WCAG 1.4.4; px is reserved for
 * hairline geometry that deliberately should not).
 *
 * Card width is deliberately the ONLY thing that varies per breakpoint here — height is never set
 * anywhere in this recipe. ZimmProductCardMedia's own `slide` part already carries
 * `aspectRatio: '2 / 3'` at `width: '100%'` (zimmProductCardMedia.css.ts), and ZimmProductCard's
 * own root has no height opinion of its own (zimmProductCard.css.ts) — so once `card` below gives
 * each item a fixed width and nothing in the chain overrides height, the card's rendered height
 * falls out of that aspect-ratio math for free, matching this step's own "don't hardcode a
 * height" instruction.
 *
 * GROUP HAS ZERO GAP / ZERO HORIZONTAL PADDING — not an oversight. The given per-breakpoint
 * card-width x visible-count figures multiply out to exactly that breakpoint's design viewport
 * width with nothing left over (201x2=402, 256x3=768, 288x5=1440); that arithmetic only holds if
 * there is no gap between cards and no horizontal inset on the scroll container itself. `header`
 * (the title-and-link row) is given the same zero-inset treatment here for consistency — this
 * half is a judgment call, not a confirmed Figma reading: no explicit horizontal-inset
 * measurement for the title row was supplied in this step's brief, and the base SFCC
 * ProductScroller this branch eventually replaces isn't a usable precedent either way (it pads
 * its own scroll row at `px={{base: 4, md: 8, lg: 0}}` and leaves its own centred title with no
 * horizontal margin at all — node_modules/@salesforce/retail-react-app/app/components/
 * product-scroller/index.jsx:76 — a different split again). Flagged for confirmation once this
 * rail sits inside a real page (A6): getting it wrong shows up as either a doubled-up margin or a
 * flush-to-viewport-edge title, not a test failure, since this component has no assigned page
 * context of its own.
 *
 * HEADER HEIGHT — two states, not three: 56px at base (covers Mobile and Tablet — the build
 * plan's own brief gives exactly one Mobile header node and one Desktop header node, no separate
 * Tablet one), stepping to 96px from Desktop (breakpoints.xl) up. Same rem-with-pending-comment
 * treatment as the card widths above — neither 56px nor 96px has an existing --zimm-scale-*
 * equivalent either.
 *
 * SEE-ALL LINK — colour/hover/focus-visible states only. Typography (uppercase, underline, size,
 * weight) comes from the `textStyle="linkLg"` prop applied directly in index.tsx
 * (typography.ts:152), not duplicated here as a recipe value — see
 * .claude/rules/overrideStyling.md hierarchy point 1 (textStyle before var(--zimm-*)). Colours
 * resolved from the registry, not re-derived: default var(--zimm-color-link-default), hover
 * var(--zimm-color-link-hover), focus ring var(--zimm-focus-ring) /
 * var(--zimm-focus-ring-offset-default) (zimmTokens.ts:68-69).
 *
 * No Figma hover/focus/active variant exists for this link — only a single "State=default" node
 * was supplied (see index.tsx's own comment on the same point for the full caveat). `active`
 * deliberately has no rule of its own below and simply inherits whatever `_hover` establishes —
 * see that key's own inline comment for why that is intentional, not a missed state.
 *
 * Parts: `container`, `header`, `seeAllLink`, `group`, `card` — reconciled against index.tsx's own
 * `useMultiStyleConfig` reads by `ui-kits/recipeParts.test.ts`.
 */

// Card width — see docblock. rem, not px, matching footer.css.ts's SIZE_COL_SUB/SIZE_COL_MAP
// precedent for a sizing (non-hairline) dimension with no foundation token yet.
const CARD_WIDTH_MOBILE = '12.5625rem'; // 201px — confirmed Figma value (Mobile, node 40000538:25030). No --zimm-scale-* equivalent (nearest neighbours: 1300=52px, 1600=64px) — pending promotion to foundation/spacing.ts or sizes.ts by the UI designer.
const CARD_WIDTH_TABLET = '16rem'; // 256px — confirmed Figma value (Tablet, node 40000730:13363). No --zimm-scale-* equivalent — pending promotion, same as above.
const CARD_WIDTH_DESKTOP = '18rem'; // 288px — confirmed Figma value (Desktop, node 40000307:12444). No --zimm-scale-* equivalent — pending promotion, same as above.

// Header (title-and-link row) height — see docblock. Same pending-token treatment as the card
// widths above; neither value exists anywhere in zimmTokens.ts's numeric scale.
const HEADER_HEIGHT_MOBILE = '3.5rem'; // 56px — confirmed Figma value (node 40000538:25031, Mobile — also covers Tablet, see docblock). Pending promotion.
const HEADER_HEIGHT_DESKTOP = '6rem'; // 96px — confirmed Figma value (node 40000538:20306, Desktop). Pending promotion.

// Deliberately NOT named DESKTOP_QUERY / sharing zimmProductCardShared.ts's constant of that
// name: that one gates at breakpoints.md (768px, the product-card family's own "show the bag icon
// again" threshold) — a different breakpoint for a different concern. Reusing the name here would
// read as the same threshold when it isn't.
const TABLET_UP_QUERY = `@media (min-width: ${breakpoints.md})`; // 768px — card width only; header has no separate Tablet step, see docblock.
const DESKTOP_UP_QUERY = `@media (min-width: ${breakpoints.xl})`; // 1280px — the "Desktop" tier for both card width and header height.

export const ZimmRecentlyViewedRail = {
  parts: ['container', 'header', 'seeAllLink', 'group', 'card'],

  baseStyle: (): Record<string, SystemStyleObject> => ({
    container: {
      width: '100%',
    },

    header: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      height: HEADER_HEIGHT_MOBILE,
      [DESKTOP_UP_QUERY]: {
        height: HEADER_HEIGHT_DESKTOP,
      },
    },

    seeAllLink: {
      // WCAG 2.2 AA SC 2.5.8 — 24px minimum target. This link sits alone in its own row (not
      // inline within a sentence), so the inline-text exemption doesn't apply, and `linkLg`'s
      // line-height (16px) is under the threshold on its own. Same fix, same token, as
      // zimmLink.css.ts's own baseStyle for the identical concern.
      display: 'inline-block',
      paddingBlock: 'var(--zimm-scale-2xs)',
      color: 'var(--zimm-color-link-default)',
      _hover: {
        color: 'var(--zimm-color-link-hover)',
      },
      // No distinct `active` token exists anywhere in the design system for this link (see the
      // module docblock) — deliberately no `_active` rule here. A pointer is already over the
      // link while pressing it in the normal (non-keyboard) case, so `_hover` above keeps
      // matching through the press and "active" ends up the same colour as hover by inheritance.
      // This is intentional, not a missed state.
      _focusVisible: {
        outline: 'var(--zimm-focus-ring)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },

    group: {
      display: 'flex',
      width: '100%',
      // Zero gap, zero horizontal padding — see module docblock's "GROUP HAS ZERO GAP" note; the
      // given card-width x visible-count figures only add up to the design viewport width with
      // neither present.
      gap: 0,
      overflowX: 'auto',
      scrollSnapType: 'x mandatory',
      // Safari touch scrolling needs this for scroll-snap to feel native — same precedent as
      // zimmProductCardMedia.css.ts's own scrollContainer part.
      WebkitOverflowScrolling: 'touch',
      // This is a paged card rail, not a general-purpose scroll region — native scrollbar
      // suppressed for the same reason zimmProductCardMedia.css.ts's scrollContainer suppresses
      // its own.
      scrollbarWidth: 'none',
      '&::-webkit-scrollbar': { display: 'none' },
    },

    card: {
      flex: `0 0 ${CARD_WIDTH_MOBILE}`,
      width: CARD_WIDTH_MOBILE,
      scrollSnapAlign: 'start',
      [TABLET_UP_QUERY]: {
        flex: `0 0 ${CARD_WIDTH_TABLET}`,
        width: CARD_WIDTH_TABLET,
      },
      [DESKTOP_UP_QUERY]: {
        flex: `0 0 ${CARD_WIDTH_DESKTOP}`,
        width: CARD_WIDTH_DESKTOP,
      },
    },
  }),
};

