{/* Body  */}
<Grid templateColumns={{ base: '1fr', md: '280px 1fr' }} columnGap={6}>
  <Stack display={{ base: 'none', md: 'flex' }}>
    <Island hydrateOn={'visible'}>
      <Refinements
        itemsBefore={
          category?.categories
            ? [
                <CategoryLinks key="itemsBefore" category={category} onSelect={onClose} />,
                createStoreInventoryFilter(),
              ].filter(Boolean)
            : [createStoreInventoryFilter()].filter(Boolean)
        }
        isLoading={filtersLoading}
        toggleFilter={toggleFilter}
        filters={productSearchResult?.refinements}
        excludedFilters={['cgid']}
        selectedFilters={searchParams.refine}
      />
    </Island>
  </Stack>
  <Box>
    {showNoResults ? (
      <EmptySearchResults searchQuery={searchQuery} category={category} />
    ) : (
      <>
        <SimpleGrid columns={[2, 2, 4, 5]} spacingX={4} spacingY={{ base: 12, lg: 16 }}>
          {isHydrated() && ((isRefetching && !isFetched) || !productSearchResult)
            ? new Array(searchParams.limit).fill(0).map((_value, index) => <ProductTileSkeleton key={index} />)
            : productSearchResult?.hits?.map((productSearchItem) => {
                // SFCC-83/84 quick test integration: ZimmProductCard's `plp` variation has
                // no wishlist-toggle affordance at all (only `wishlist` variation has a
                // remove/heart control) — the base ProductTile's `enableFavourite`/
                // `isFavourite`/`onFavouriteToggle` (and the per-item `isInWishlist` lookup
                // that fed it) have no equivalent here, so that per-item computation was
                // removed rather than left dead. `addItemToWishlist`/`removeItemFromWishlist`
                // themselves are untouched above — still there for whenever this affordance
                // gets a real home on this grid.
                const card = selectProductListCard(productSearchItem, formatPrice);
                if (!card) return null;

                const handleAddToBag = () => {
                  // `representedProduct?.id`, not the hit's own top-level `productId`
                  // directly: for a colour/size-variant product, PLP search hits are
                  // represented at the master level, and a master has no SKU — only its
                  // variants do (`ShopperSearchTypes.Variant`'s own real SDK doc: "Has a
                  // SKU"). `representedProduct` is the SDK's own already-resolved variant
                  // reference for this hit; falls back to `productId` for a simple,
                  // non-variant product where the two are the same thing anyway.
                  const orderableProductId = productSearchItem.representedProduct?.id ?? productSearchItem.productId;
                  addItemToNewOrExistingBasket([
                    { productId: orderableProductId, price: productSearchItem.price, quantity: 1 },
                  ])
                    .then(() => toast({ title: intl.formatMessage(messages.addedToBag), status: 'success' }))
                    .catch(() => toast({ title: intl.formatMessage(API_ERROR_MESSAGE), status: 'error' }));
                };

                return (
                  <Island hydrateOn={'visible'} key={productSearchItem.productId}>
                    {/* Wraps rather than passing an onClick prop — ZimmProductCard exposes
                        no generic click callback, but a click anywhere in the card (the
                        image or the name link) still bubbles up through this wrapper. */}
                    <Box
                      onClick={() => {
                        if (searchQuery) {
                          einstein.sendClickSearch(searchQuery, productSearchItem);
                        } else if (category) {
                          einstein.sendClickCategory(category, productSearchItem);
                        }
                      }}
                    >
                      <ProductListCard {...card} onAddToBag={handleAddToBag} />
                    </Box>
                  </Island>

                  );
                })}
          </SimpleGrid>
          {/* Footer */}
          <Flex justifyContent={['center', 'center', 'flex-start']} paddingTop={8}>
            <Pagination currentURL={basePath} urls={pageUrls} />

            {/*
          Our design doesn't call for a page size select. Show this element if you want
          to add one to your design.
      */}
            <Select
              display="none"
              value={basePath}
              onChange={({ target }: React.ChangeEvent<HTMLSelectElement>) => {
                history.push(target.value);
              }}
            >
              {limitUrls.map((href: string, index: number) => (
                <option key={href} value={href}>
                  {DEFAULT_LIMIT_VALUES[index]}
                </option>
              ))}
            </Select>
          </Flex>
        </>
      )}
    </Box>
  </Grid>
</>
{/* Recently Viewed rail — SFCC-83 AC 9 (PLP surface). Full-width, edge-to-edge horizontal
    scroller (see ZimmRecentlyViewedRail), so it sits outside the column-constrained Grid
    above rather than inside either of its two branches. Renders unconditionally regardless
    of showNoResults: a recently-viewed rail is arguably *more* useful as a recovery aid on a
    no-results search than on a normal results page, and every other Einstein rail in this
    codebase (PDP, Cart) already renders regardless of that page's own primary-content state
    — see product-detail/index.tsx's three <RecommendedProducts> usages, none of which are
    conditioned on PDP's own loading/error state either. `mx` matches this page's own
    layerStyle="page" bleed pattern, which product-detail/index.tsx shares byte-for-byte
    (both pages' outer <Box> use layerStyle="page") — so the identical mx value PDP already
    uses to bleed this same component edge-to-edge (product-detail/index.tsx's
    PDP_RECENTLY_VIEWED usage) applies cleanly here too. Not Cart's own mx value: base
    Cart's container (node_modules/@salesforce/retail-react-app/app/pages/cart/index.jsx)
    uses a different, non-layerStyle container altogether, so it isn't the right precedent
    for a page built on layerStyle="page". `key={location.key}` matches PDP's own
    Recently-Viewed usage for the same reason it exists there: this recommender ignores
    `products`, so without a location-keyed remount, navigating between categories/searches
    (which reuses this same route component rather than remounting it) would never refresh
    the rail's contents. No `title`/`seeAllHref`/`seeAllLabel` yet — those are supplied by a
    separate, not-yet-built step; an untitled rail with no See-Full-History link is the
    correct intermediate state for this phase. */}
<Island hydrateOn={'visible'}>
  <RecommendedProducts
    key={location.key}
    recommender={EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED}
    mx={{ base: -4, md: -8, lg: 0 }}
  />
</Island>
