/**
 * Zimmermann country configuration — combines SCAPI-derived site/locale/
 * currency truth (countries.generated.ts, regenerate via
 * `npm run sync:regional-config`) with a hand-maintained overlay for the
 * fields Business Manager/SCAPI has no concept of: shipping country,
 * checkout ownership, and boutique region grouping.
 *
 * Used by: URL routing, IP-detection prompt, checkout redirect logic,
 * boutique location filtering, hreflang generation.
 *
 * When adding a country:
 *   1. Add it to config/sites.overlay.js (and e2e/fixtures/site.overlay.js
 *      if it needs e2e coverage), then run `npm run sync:regional-config`.
 *   2. Add its business-logic overlay entry below (shippingCountry,
 *      checkoutOwner, globalEPricing, boutiqueRegion).
 *   3. Ensure a compiled translation exists in overrides/app/static/translations/compiled/.
 *
 * Unresolved — do not hard-code:
 *   - NZ/Oceania currency routing
 *   - Denmark routing
 *   - China
 */

import { GENERATED_COUNTRIES } from './countries.generated';

/**
 * Who owns checkout for this site's domestic path.
 * For HK and ME, Global-e always owns checkout AND pricing from PDP onward.
 * For AU, US, GB, EU: SFCC owns domestic paths; Global-e takes over when the
 * user's shipping destination is outside the site's domestic market.
 */
export type CheckoutOwner = 'sfcc' | 'global-e' | 'hybrid';

export type CountryConfig = {
  /** URL path segment, e.g. 'au', 'us', 'fr-eu' */
  urlSlug: string;
  /** The real SFCC site this locale routes to */
  sfccSiteId: string;
  /** IETF locale used by PWA Kit / SFCC, e.g. 'en-AU' */
  locale: string;
  /** ISO 4217 currency code */
  currency: string;
  /** ISO 3166-1 alpha-2 shipping/tax country */
  shippingCountry: string;
  /**
   * Checkout owner for this site's domestic path.
   * Branch checkout AND pricing logic from this field at PDP/cart level —
   * not only at the checkout page.
   */
  checkoutOwner: CheckoutOwner;
  /**
   * When true, Global-e owns pricing, currency, and tax display from PDP
   * onward — do not render SFCC prices on these paths.
   */
  globalEPricing: boolean;
  /** Key used to filter boutique locations for this region */
  boutiqueRegion: string;
};

type CountryOverlayEntry = Pick<
  CountryConfig,
  'shippingCountry' | 'checkoutOwner' | 'globalEPricing' | 'boutiqueRegion'
>;

/**
 * Hand-maintained business/geo data, keyed the same way as
 * countries.generated.ts (URL slug; 'au' for the root/default site).
 *
 * 'en-ca' (US international) is defined here ready to go, but has no
 * matching entry in countries.generated.ts yet — it's excluded from the
 * final COUNTRIES export below until the ZimmermannUSIntl site is added to
 * config/sites.overlay.js (pending BM confirmation of the real site ID —
 * see .docs/planning/regionalConfigSyncPlan.md).
 */
const COUNTRY_OVERLAY: Record<string, CountryOverlayEntry> = {
  au: { shippingCountry: 'AU', checkoutOwner: 'sfcc', globalEPricing: false, boutiqueRegion: 'australia' },
  us: { shippingCountry: 'US', checkoutOwner: 'hybrid', globalEPricing: false, boutiqueRegion: 'usa' },
  'en-ca': { shippingCountry: 'CA', checkoutOwner: 'global-e', globalEPricing: true, boutiqueRegion: 'usa' }, // TBC — pending ZimmermannUSIntl
  uk: { shippingCountry: 'GB', checkoutOwner: 'sfcc', globalEPricing: false, boutiqueRegion: 'uk' },
  'en-eu': { shippingCountry: 'DE', checkoutOwner: 'sfcc', globalEPricing: false, boutiqueRegion: 'europe' }, // placeholder; shipping country resolved at checkout
  'fr-eu': { shippingCountry: 'FR', checkoutOwner: 'sfcc', globalEPricing: false, boutiqueRegion: 'europe' },
  'it-eu': { shippingCountry: 'IT', checkoutOwner: 'sfcc', globalEPricing: false, boutiqueRegion: 'europe' }, // placeholder; shipping country resolved at checkout
  'es-eu': { shippingCountry: 'ES', checkoutOwner: 'sfcc', globalEPricing: false, boutiqueRegion: 'europe' }, // placeholder; shipping country resolved at checkout
  'en-ch': { shippingCountry: 'CH', checkoutOwner: 'global-e', globalEPricing: true, boutiqueRegion: 'europe' }, // placeholder; Global-e resolves shipping country
  hk: { shippingCountry: 'HK', checkoutOwner: 'global-e', globalEPricing: true, boutiqueRegion: 'hong-kong' },
  'en-ae': { shippingCountry: 'AE', checkoutOwner: 'global-e', globalEPricing: true, boutiqueRegion: 'middle-east' },
};

/**
 * Keyed by urlSlug for O(1) lookup in routing/middleware.
 * AU is the exception: it has no URL prefix (root domain). Its key is 'au'
 * but urlSlug is '' — routing falls back to DEFAULT_COUNTRY_SLUG when no
 * prefix is detected.
 */
// Fail loud, not silent, if BM/the sync script produced a slug with no
// matching business-logic overlay — that means someone added a site to
// config/sites.overlay.js and ran `npm run sync:regional-config` without
// adding the corresponding COUNTRY_OVERLAY entry above. The reverse case
// (an overlay entry with no generated data yet, e.g. 'en-ca' pending the
// US-split site ID) is intentional and handled by the filter below instead.
const missingOverlays = Object.keys(GENERATED_COUNTRIES).filter((slug) => !(slug in COUNTRY_OVERLAY));
if (missingOverlays.length) {
  throw new Error(
    `countries.ts: config/sites.overlay.js has a site for slug(s) '${missingOverlays.join(', ')}' with no ` +
      `matching COUNTRY_OVERLAY entry — add shippingCountry/checkoutOwner/globalEPricing/boutiqueRegion for it.`,
  );
}

export const COUNTRIES: Record<string, CountryConfig> = Object.fromEntries(
  Object.entries(COUNTRY_OVERLAY)
    .filter(([slug]) => slug in GENERATED_COUNTRIES)
    .map(([slug, overlay]) => [
      slug,
      {
        urlSlug: slug === 'au' ? '' : slug,
        ...(GENERATED_COUNTRIES as Record<string, { sfccSiteId: string; locale: string; currency: string }>)[slug],
        ...overlay,
      },
    ]),
);

/** Fallback when no URL slug is present or IP detection fails. */
export const DEFAULT_COUNTRY_SLUG = 'au';

/** Lookup by ISO 3166-1 alpha-2 code — used by IP-detection prompt. */
export const COUNTRY_BY_SHIPPING_CODE: Record<string, CountryConfig> = Object.fromEntries(
  Object.values(COUNTRIES).map((c) => [c.shippingCountry, c]),
);

// represented at the master level, and a master has no SKU — only its
// variants do (`ShopperSearchTypes.Variant`'s own real SDK doc: "Has a
// SKU"). `representedProduct` is the SDK's own already-resolved variant
// reference for this hit; falls back to `productId` for a simple,
// non-variant product where the two are the same thing anyway.
const orderableProductId = productSearchItem.representedProduct?.id ?? productSearchItem.productId;
addItemToNewOrExistingBasket([
  { productId: orderableProductId, price: productSearchItem.price, quantity: 1 },
])
  .then(() => toast({ title: intl.formatMessage(messages.addedToBag), status: 'success' }))
